  function saveReport(){const date=$('report-date').value;if(!date){notify('Seleziona una data valida.');return;}let client=null,site=null,room=null;if(selectedType==='LAVORO'){client=db.clienti.find(c=>c.id===$('customer-select').value);if(!client){notify('Seleziona un cliente.');return;}site=client.cantieri.find(s=>s.id===$('site-select').value)||null;room=site?.interni.find(r=>r.id===$('room-select').value)||null;}const expense=Number(String($('expenses').value||0).replace(',','.'));if(!Number.isFinite(expense)||expense<0){notify('Inserisci spese valide.');return;}const dateText=dateDisplay(date);const duplicate=db.rapportini.some(r=>r.data===dateText&&(selectedType==='LAVORO'?r.tipologia==='LAVORO'&&r.cantiereId===(site?.id||null)&&r.internoId===(room?.id||null):r.tipologia===selectedType));if(duplicate&&!confirm('Hai già inserito una voce simile in questa data. Vuoi aggiungerne un’altra?'))return;db.rapportini.push({id:uid('rap'),data:dateText,clienteId:client?.id||'ASSENTE',clienteNome:client?.nome||'Non Specificato',cantiereId:site?.id||null,cantiereNome:site?.nome||null,internoId:room?.id||null,internoCodice:room?.codice||null,tipologia:selectedType,ore:hours,note:$('notes').value.trim(),speseAnticipate:selectedType==='LAVORO'?expense:0});saveDb().then(ok=>{if(ok){notify('Rapportino registrato.');$('notes').value='';$('expenses').value='0';refreshHoursFromDailyRemainder();}});}
