  function fmt(n){return Number(n||0).toLocaleString('it-IT',{maximumFractionDigits:2});}
  function fmtPrecise(n,digits=3){return Number(n||0).toLocaleString('it-IT',{maximumFractionDigits:digits});}
  function weekdaysElapsed(y,m){const now=new Date(),end=new Date(y,m+1,0).getDate(),limit=y===now.getFullYear()&&m===now.getMonth()?now.getDate():new Date(y,m,1)>now?0:end;let count=0;for(let day=1;day<=limit;day++){const d=new Date(y,m,day);const iso=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;if(d.getDay()!==0&&d.getDay()!==6&&!isHoliday(iso))count++;}return count;}
  async function deleteReport(id){const report=db.rapportini.find(item=>item.id===id);if(!report||!confirm('Eliminare questo rapportino?'))return;if(cloudMembership?.status==='active'&&(!report.owner_user_id||report.owner_user_id===CloudRegistro.currentUserId())){if(!navigator.onLine){notify('Per eliminare un rapportino sincronizzato serve la connessione.');return;}try{await CloudRegistro.deleteOwnReport(cloudMembership.workspace_id,id);}catch(error){notify(`Eliminazione cloud non riuscita: ${error.message}`);return;}}db.rapportini=db.rapportini.filter(item=>item.id!==id);saveDb();refreshHoursFromDailyRemainder();}
  function editReport(id){const r=db.rapportini.find(x=>x.id===id);if(!r)return;const h=prompt('Ore totali',String(r.ore));if(h===null)return;const hoursValue=Number(String(h).replace(',','.'));if(!Number.isFinite(hoursValue)||hoursValue<0||hoursValue>24){notify('Valore ore non valido.');return;}const notes=prompt('Note',r.note);if(notes===null)return;let exp=r.speseAnticipate||0;if(r.tipologia==='LAVORO'){const e=prompt('Spese anticipate (€)',String(exp));if(e===null)return;exp=Number(String(e).replace(',','.'));if(!Number.isFinite(exp)||exp<0){notify('Importo spese non valido.');return;}}Object.assign(r,{ore:hoursValue,note:notes,speseAnticipate:exp});saveDb();refreshHoursFromDailyRemainder();}
  function monthChange(delta){month+=delta;if(month<0){month=11;year--;}if(month>11){month=0;year++;}renderBoard();}
  function checkGaps(){const limit=year===new Date().getFullYear()&&month===new Date().getMonth()?new Date().getDate():new Date(year,month+1,0).getDate();const reported=new Set(db.rapportini.map(r=>{const [d,m,y]=dateParts(r.data);return `${y}-${m}-${d}`;}));const missing=[];for(let day=1;day<=limit;day++){const date=new Date(year,month,day),iso=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;if(date.getDay()!==0&&date.getDay()!==6&&!isHoliday(iso)&&!reported.has(`${year}-${month+1}-${day}`))missing.push(`${String(day).padStart(2,'0')}/${String(month+1).padStart(2,'0')}/${year}`);}alert(missing.length?`Rapportini mancanti:\n\n${missing.join('\n')}`:'Nessun giorno feriale mancante nel periodo.');}
