      const sites=candidate.clienti.reduce((sum,c)=>sum+c.cantieri.length,0);
      if(!confirm(`Sostituire i dati attuali con ${candidate.clienti.length} clienti, ${sites} cantieri, ${candidate.rapportini.length} rapportini e ${photos} foto? Prima sarà salvata una copia recuperabile.`))return;
